        case .badDeliveryId: 400
        case .unauthenticated: 401
        case .badSignature: 401
        case .unauthorized: 401
        case .forbidden: 403
        case .accountDeleted: 403
        case .notFound: 404
        case .unknownComputer: 404
        case .alreadyClaimed: 409
        case .conflict: 409
        case .tooMany: 409
        case .inviteUsed: 409
        case .paused: 409
        case .claimExpired: 410
